import numpy as np

def relu(z):
    return np.maximum(z, 0)

def residual_block(x, W1, W2):
    return x + W2 @ relu(W1 @ x)

def residual_proj(x, W1, W2, P):
    return P @ x + W2 @ relu(W1 @ x)
